election\\", False):\\n                self._multi_selection = False\\n                self._clear_form()\\n            return\\n        self._multi_selection = False\\n        set_form_state(self, False)\\n        self.selected_index = int(sel[0])\\n        row = self.rows[self.selected_index]\\n        for f in self.spec.fields:\\n            self.vars[f.name].set(row.get(f.name, \\"\\"))\\n        self._ref_choices()\\n\\n"], ["doda_network_editor.py", "            open_bulk_editor(\\n                self, validate_candidate, reference_keys, evidence_choices,\\n                collection_model_rules.decimal_value,\\n            )", "            apply_inline(self, validate_candidate, collection_model_rules.decimal_value)"], ["doda_multiselect.py", "            if selected else \\"Select evidence types...\\"", "            if selected else (\\"\\" if getattr(self, \\"_bulk_mode\\", False) else \\"Select evidence types...\\")"], ["doda_multiselect.py", "        self.variable.set(merged_selection(\\n            self.variable.get(), self.options, checked\\n        ))", "        raw = self.variable.get()\\n        if getattr(self, \\"_bulk_mode\\", False) and raw == \\"Multiple values\\":\\n            raw = \\"\\"\\n        self.variable.set(merged_selection(raw, self.options, checked))"]], "replacements_full": {"doda_bulk_edit.py": "\\"\\"\\"Explicit, atomic draft-only batch editing for shared table pages.\\"\\"\\"\\nimport csv\\n\\nfrom doda_row_selection import MULTIPLE_VALUES, selection_display\\n\\n\\nclass BulkEditError(ValueError):\\n    pass\\n\\n\\ndef build_candidate(rows, indices, changes, spec, decimal_check=None):\\n    indices = tuple(indices)\\n    if len(indices) < 2 or len(set(indices)) != len(indices):\\n        raise BulkEditError(\\"Select at least two distinct rows.\\")\\n    if any(not isinstance(i, int) or i < 0 or i >= len(rows) for i in indices):\\n        raise BulkEditError(\\"Selection no longer matches the draft.\\")\\n    fields = {f.name: f for f in spec.fields}\\n    for name, value in changes.items():\\n        if name not in fields:\\n            raise BulkEditError(\\"Unknown field: \\" + name)\\n        if name in spec.key_columns:\\n            raise BulkEditError(\\"Identity fields cannot be batch-edited: \\" + name)\\n        if not isinstance(value, str):\\n            raise BulkEditError(\\"Field values must be text: \\" + name)\\n        if value.strip() == MULTIPLE_VALUES or (\\n            fields[name].kind == \\"evidence_multi\\"\\n            and MULTIPLE_VALUES in [v.strip() for v in value.split(\\";\\")]\\n        ):\\n            raise BulkEditError(\\"Placeholder text cannot be applied: \\" + name)\\n    candidate = [dict(row) for row in rows]\\n    for index in indices:\\n        candidate[index].update({name: value.strip() for name, value in changes.items()})\\n        row = candidate[index]\\n        for f in spec.fields:\\n            value = row.get(f.name, \\"\\")\\n            if f.required and not value.strip():\\n                raise BulkEditError(f\\"Row {index + 1}: {f.label} is required.\\")\\n            if value and f.kind == \\"int\\":\\n                try:\\n                    int(value)\\n                except ValueError:\\n                    raise BulkEditError(f\\"Row {index + 1}: {f.label} must be a whole number.\\")\\n            if value and f.kind == \\"decimal\\" and decimal_check is not None:\\n                try:\\n                    decimal_check(value)\\n                except ValueError as error:\\n                    raise BulkEditError(f\\"Row {index + 1}: {f.label}: {error}\\") from error\\n            if f.name in changes and value:\\n                if f.kind == \\"bool\\" and value.lower() not in (\\"true\\", \\"false\\"):\\n                    raise BulkEditError(f\\"{f.label} must be true or false.\\")\\n                if f.kind == \\"choice\\" and f.choices and value not in f.choices:\\n                    raise BulkEditError(f\\"{f.label}: select an available choice.\\")\\n    keys = [tuple(row.get(k, \\"\\") for k in spec.key_columns) for row in candidate]\\n    if any(any(not value.strip() for value in key) for key in keys):\\n        raise BulkEditError(\\"Draft contains a blank identity key.\\")\\n    if len(keys) != len(set(keys)):\\n        raise BulkEditError(\\"Draft contains duplicate identity keys.\\")\\n    return candidate\\n\\n\\ndef apply_to_draft(editor, selection, original_rows, changes, validate, decimal_check=None):\\n    if tuple(editor.tree.selection()) != tuple(selection) or editor.rows != original_rows:\\n        raise BulkEditError(\\"Draft or selection changed. Reselect the rows before applying.\\")\\n    if not changes:\\n        return False\\n    candidate = build_candidate(\\n        original_rows, [int(item) for item in selection], changes,\\n        editor.spec, decimal_check,\\n    )\\n    result = validate(editor.app.project_root, editor.spec.table, candidate)\\n    if not result.valid:\\n        raise BulkEditError(\\"Batch validation failed; no rows changed.\\\\n\\\\n\\" + \\"\\\\n\\".join(result.errors[:12]))\\n    if tuple(editor.tree.selection()) != tuple(selection) or editor.rows != original_rows:\\n        raise BulkEditError(\\"Draft or selection changed during validation. No rows changed.\\")\\n    editor.rows = candidate\\n    editor.dirty = True\\n    return True\\n", "tests/test_row_selection.py": "import ast\\nimport inspect\\nimport textwrap\\nimport unittest\\nfrom types import SimpleNamespace\\nfrom unittest.mock import Mock, patch\\nimport doda_row_selection as selection\\nimport doda_network_editor as shared\\nimport doda_task_templates_editor as tasks\\n\\n\\nclass Variable:\\n    def __init__(self, value=\\"\\"):\\n        self.value = value\\n        self.callbacks = []\\n    def trace_add(self, mode, callback):\\n        self.callbacks.append(callback)\\n        return str(len(self.callbacks))\\n    def get(self):\\n        return self.value\\n    def set(self, value):\\n        self.value = value\\n        for callback in self.callbacks:\\n            callback()\\n\\n\\nclass Widget:\\n    def __init__(self, state=\\"normal\\"):\\n        self.state = state\\n    def cget(self, name):\\n        return () if name == \\"values\\" else self.state\\n    def configure(self, **kwargs):\\n        self.state = kwargs.get(\\"state\\", self.state)\\n    def bind(self, *args, **kwargs):\\n        pass\\n\\n\\nclass RowSelectionTests(unittest.TestCase):\\n    def shared_editor(self):\\n        fields = [\\n            SimpleNamespace(name=name, kind=\\"text\\")\\n            for name in (\\"id\\", \\"value\\", \\"blank\\")\\n        ]\\n        rows = [\\n            {\\"id\\": \\"A\\", \\"value\\": \\"1\\", \\"blank\\": \\"\\"},\\n            {\\"id\\": \\"B\\", \\"value\\": \\"2\\", \\"blank\\": \\"\\"},\\n        ]\\n        tree = Mock()\\n        tree.selection.return_value = (\\"0\\", \\"1\\")\\n        return SimpleNamespace(\\n            title=\\"Test\\", tree=tree, rows=rows,\\n            spec=SimpleNamespace(fields=fields, key_columns=(\\"id\\",)),\\n            selected_index=0,\\n            vars={f.name: Variable() for f in fields},\\n            widgets={\\n                f.name: Widget(\\"readonly\\" if f.name == \\"id\\" else \\"normal\\")\\n                for f in fields\\n            },\\n            _ref_choices=Mock(), _set_status=Mock(), _clear_form=Mock(),\\n            _form_row=Mock(), dirty=False,\\n        )\\n\\n    def test_extended_selection_configured_on_both_tables(self):\\n        for method in (\\n            shared.NetworkTableEditor._build,\\n            tasks.TaskTemplatesEditor.build,\\n        ):\\n            tree = ast.parse(textwrap.dedent(inspect.getsource(method)))\\n            modes = [\\n                kw.value.value\\n                for node in ast.walk(tree) if isinstance(node, ast.Call)\\n                for kw in node.keywords\\n                if kw.arg == \\"selectmode\\" and isinstance(kw.value, ast.Constant)\\n            ]\\n            self.assertIn(\\"extended\\", modes)\\n\\n    def test_display_blank_and_occupied_fields(self):\\n        self.assertEqual(\\n            selection.selection_display([{\\"x\\": \\"\\"}, {\\"x\\": \\"\\"}], \\"x\\"), \\"\\"\\n        )\\n        self.assertEqual(\\n            selection.selection_display([{\\"x\\": \\"1\\"}, {\\"x\\": \\"1\\"}], \\"x\\"),\\n            \\"Multiple values\\",\\n        )\\n        self.assertEqual(\\n            selection.selection_display([{\\"x\\": \\"\\"}, {\\"x\\": \\"1\\"}], \\"x\\"),\\n            \\"Multiple values\\",\\n        )\\n\\n    def test_single_selection_action_allowed(self):\\n        obj = self.shared_editor()\\n        obj.tree.selection.return_value = (\\"0\\",)\\n        dialogs = Mock()\\n        self.assertTrue(selection.require_single(obj, \\"Apply\\", dialogs))\\n        dialogs.showwarning.assert_not_called()\\n\\n    def test_multiple_selection_action_blocked(self):\\n        obj = self.shared_editor()\\n        dialogs = Mock()\\n        self.assertFalse(selection.require_single(obj, \\"Apply\\", dialogs))\\n        dialogs.showwarning.assert_called_once()\\n\\n    def test_shared_multiple_selection_is_editable_with_protected_keys_and_preserves_rows(self):\\n        obj = self.shared_editor()\\n        before = [dict(row) for row in obj.rows]\\n        shared.NetworkTableEditor._on_select(obj)\\n        self.assertIsNone(obj.selected_index)\\n        self.assertEqual(obj.vars[\\"value\\"].get(), \\"Multiple values\\")\\n        self.assertEqual(obj.vars[\\"blank\\"].get(), \\"\\")\\n        self.assertEqual(obj.widgets[\\"id\\"].state, \\"disabled\\")\\n        self.assertEqual(obj.widgets[\\"value\\"].state, \\"normal\\")\\n        self.assertEqual(obj.widgets[\\"blank\\"].state, \\"normal\\")\\n        self.assertEqual(obj._inline_bulk.changes, {})\\n        self.assertEqual(obj.rows, before)\\n        self.assertFalse(obj.dirty)\\n\\n    def test_return_to_single_selection_restores_fields(self):\\n        obj = self.shared_editor()\\n        shared.NetworkTableEditor._on_select(obj)\\n        obj.tree.selection.return_value = (\\"1\\",)\\n        shared.NetworkTableEditor._on_select(obj)\\n        self.assertEqual(obj.selected_index, 1)\\n        self.assertEqual(obj.vars[\\"value\\"].get(), \\"2\\")\\n        self.assertEqual(obj.widgets[\\"id\\"].state, \\"readonly\\")\\n        self.assertEqual(obj.widgets[\\"value\\"].state, \\"normal\\")\\n        self.assertEqual(obj._ref_choices.call_count, 2)\\n\\n    def test_deselect_last_row_clears_multiple_state(self):\\n        obj = self.shared_editor()\\n        shared.NetworkTableEditor._on_select(obj)\\n        obj.tree.selection.return_value = ()\\n        shared.NetworkTableEditor._on_select(obj)\\n        self.assertFalse(obj._multi_selection)\\n        self.assertIsNone(obj.selected_index)\\n        obj._clear_form.assert_called_once()\\n        self.assertEqual(obj.widgets[\\"value\\"].state, \\"normal\\")\\n\\n    def test_task_template_multiple_selection_preserves_rows(self):\\n        tree = Mock()\\n        tree.selection.return_value = (\\"A\\", \\"B\\")\\n        rows = [\\n            dict(task_template_id=\\"A\\", display_name=\\"One\\",\\n                 description=\\"First\\", capability_id=\\"\\"),\\n            dict(task_template_id=\\"B\\", display_name=\\"Two\\",\\n                 description=\\"Second\\", capability_id=\\"\\"),\\n        ]\\n        obj = SimpleNamespace(\\n            tree=tree, loaded_rows=rows, editing_id=\\"A\\", description=Mock(),\\n            vars={\\n                name: Variable()\\n                for name in (\\"task_template_id\\", \\"display_name\\", \\"capability_id\\")\\n            },\\n            widgets={\\n                name: Widget()\\n                for name in (\\"task_template_id\\", \\"display_name\\", \\"capability_id\\")\\n            },\\n        )\\n        tasks.TaskTemplatesEditor.on_select(obj)\\n        self.assertIsNone(obj.editing_id)\\n        self.assertEqual(obj.vars[\\"display_name\\"].get(), \\"Multiple values\\")\\n        self.assertEqual(obj.vars[\\"capability_id\\"].get(), \\"\\")\\n        obj.description.insert.assert_called_once_with(\\"1.0\\", \\"Multiple values\\")\\n        self.assertEqual(rows[0][\\"display_name\\"], \\"One\\")\\n\\n    def test_shared_single_record_actions_blocked_for_multiple_rows(self):\\n        obj = self.shared_editor()\\n        with patch.object(shared.messagebox, \\"showwarning\\") as dialog:\\n            for name in (\\"delete_record\\", \\"copy_csv\\", \\"paste_csv\\"):\\n                getattr(shared.NetworkTableEditor, name)(obj)\\n        self.assertEqual(dialog.call_count, 3)\\n        obj._form_row.assert_not_called()\\n        self.assertFalse(obj.dirty)\\n\\n    def test_task_save_and_remove_blocked_for_multiple_rows(self):\\n        obj = SimpleNamespace(tree=Mock(), record=Mock(), commit=Mock())\\n        obj.tree.selection.return_value = (\\"A\\", \\"B\\")\\n        with patch.object(tasks.messagebox, \\"showwarning\\") as dialog:\\n            tasks.TaskTemplatesEditor.save(obj)\\n            tasks.TaskTemplatesEditor.remove(obj)\\n        self.assertEqual(dialog.call_count, 2)\\n        obj.record.assert_not_called()\\n        obj.commit.assert_not_called()\\n\\n    def test_shared_bulk_apply_uses_record_panel(self):\\n        obj = self.shared_editor()\\n        with patch.object(shared, \\"apply_inline\\") as apply:\\n            shared.NetworkTableEditor.apply_record(obj)\\n        apply.assert_called_once_with(\\n            obj, shared.validate_candidate, shared.collection_model_rules.decimal_value,\\n        )\\n        obj._form_row.assert_not_called()\\n        self.assertFalse(obj.dirty)\\n\\n    def test_shared_same_selection_event_keeps_pending_inline_edit(self):\\n        obj = self.shared_editor()\\n        shared.NetworkTableEditor._on_select(obj)\\n        obj.vars[\\"value\\"].set(\\"changed\\")\\n        shared.NetworkTableEditor._on_select(obj)\\n        self.assertEqual(obj.vars[\\"value\\"].get(), \\"changed\\")\\n        self.assertEqual(obj._inline_bulk.changes, {\\"value\\": \\"changed\\"})\\n        self.assertEqual(obj._ref_choices.call_count, 1)\\n\\n    def test_bulk_collection_kind_does_not_clear_untouched_fields(self):\\n        obj = self.shared_editor()\\n        shared.NetworkTableEditor._on_select(obj)\\n        before = {name: var.get() for name, var in obj.vars.items()}\\n        shared.NetworkTableEditor._collection_kind_changed(obj)\\n        self.assertEqual({name: var.get() for name, var in obj.vars.items()}, before)\\n        self.assertEqual(obj._inline_bulk.changes, {})\\n\\n    def test_bulk_prerequisite_kind_does_not_fill_untouched_fields(self):\\n        obj = self.shared_editor()\\n        shared.NetworkTableEditor._on_select(obj)\\n        before = {name: var.get() for name, var in obj.vars.items()}\\n        shared.NetworkTableEditor._prerequisite_kind_changed(obj)\\n        self.assertEqual({name: var.get() for name, var in obj.vars.items()}, before)\\n        self.assertEqual(obj._inline_bulk.changes, {})\\n"}, "new_files": {"doda_inline_bulk_edit.py": "\\"\\"\\"Inline multi-row editing; no bulk window or operation chooser.\\"\\"\\"\\nimport csv\\n\\nfrom doda_bulk_edit import BulkEditError, apply_to_draft\\nfrom doda_row_selection import MULTIPLE_VALUES, selection_display, set_form_state\\n\\nDROPDOWN_KINDS = {\\"bool\\", \\"choice\\", \\"ref\\", \\"track_ref\\", \\"task_ref\\", \\"collection_type_ref\\", \\"evidence_ref\\"}\\nREF_KINDS = {\\"ref\\", \\"track_ref\\", \\"task_ref\\", \\"collection_type_ref\\", \\"evidence_ref\\"}\\n\\n\\nclass InlineBulkEditor:\\n    def __init__(self, editor):\\n        self.editor = editor\\n        self.active = False\\n        self.loading = False\\n        self.selection = ()\\n        self.original = []\\n        self.changes = {}\\n        self.initial_values = {}\\n        self.traces = []\\n        self.fields = {f.name: f for f in editor.spec.fields}\\n        for name, field in self.fields.items():\\n            widget = editor.widgets[name]\\n            kind = getattr(field, \\"kind\\", \\"text\\")\\n            if kind in DROPDOWN_KINDS:\\n                self.initial_values[name] = widget.cget(\\"values\\")\\n            trace = editor.vars[name].trace_add(\\"write\\", lambda *_a, n=name: self.changed(n))\\n            self.traces.append((name, trace))\\n            if name in editor.spec.key_columns:\\n                continue\\n            if kind in DROPDOWN_KINDS:\\n                widget.bind(\\"<<ComboboxSelected>>\\", lambda _e, n=name: self.changed(n), add=\\"+\\")\\n            elif kind != \\"evidence_multi\\":\\n                widget.bind(\\"<FocusIn>\\", lambda _e, n=name: self.focus(n), add=\\"+\\")\\n                widget.bind(\\"<ButtonRelease-1>\\", lambda _e, n=name: self.focus(n), add=\\"+\\")\\n\\n    def same_session(self, selection):\\n        return self.active and self.selection == tuple(selection) and self.original == self.editor.rows\\n\\n    def begin(self, selection, force=False):\\n        if not force and self.same_session(selection):\\n            return\\n        self.active = False\\n        self.loading = True\\n        try:\\n            self.selection = tuple(selection)\\n            self.original = [dict(row) for row in self.editor.rows]\\n            selected = [self.original[int(item)] for item in self.selection]\\n            self.changes = {}\\n            set_form_state(self.editor, False)\\n            for name, field in self.fields.items():\\n                widget = self.editor.widgets[name]\\n                if getattr(field, \\"kind\\", \\"text\\") == \\"evidence_multi\\":\\n                    widget._bulk_mode = True\\n                self.editor.vars[name].set(selection_display(selected, name))\\n                if name in self.editor.spec.key_columns:\\n                    widget.configure(state=\\"disabled\\")\\n            self.active = True\\n        finally:\\n            self.loading = False\\n        self.editor._set_status(\\n            f\\"{len(self.selection)} rows selected - edit Record fields, then Apply to List. \\"\\n            \\"Untouched fields are preserved.\\"\\n        )\\n\\n    def end(self):\\n        self.active = False\\n        self.changes = {}\\n        self.selection = ()\\n        self.original = []\\n        for name, field in self.fields.items():\\n            if getattr(field, \\"kind\\", \\"text\\") == \\"evidence_multi\\":\\n                self.editor.widgets[name]._bulk_mode = False\\n        for name, values in self.initial_values.items():\\n            self.editor.widgets[name].configure(values=values)\\n\\n    def changed(self, name):\\n        if not self.active or self.loading or name in self.editor.spec.key_columns:\\n            return\\n        self.changes[name] = self.editor.vars[name].get()\\n        suffix = \\" UNSAVED CHANGES.\\" if self.editor.dirty else \\"\\"\\n        self.editor._set_status(\\n            f\\"{len(self.selection)} rows selected; {len(self.changes)} edited field(s) ready for Apply to List.\\" + suffix\\n        )\\n\\n    def focus(self, name):\\n        if not self.active or name in self.changes or name in self.editor.spec.key_columns:\\n            return\\n        if self.editor.vars[name].get() != MULTIPLE_VALUES:\\n            return\\n        widget = self.editor.widgets[name]\\n        def select_placeholder():\\n            if self.active and name not in self.changes and self.editor.vars[name].get() == MULTIPLE_VALUES:\\n                widget.selection_range(0, \\"end\\")\\n                widget.icursor(\\"end\\")\\n        widget.after_idle(select_placeholder)\\n\\n\\ndef install_inline(editor):\\n    controller = getattr(editor, \\"_inline_bulk\\", None)\\n    if controller is None:\\n        controller = InlineBulkEditor(editor)\\n        editor._inline_bulk = controller\\n    return controller\\n\\n\\ndef refresh_inline_choices(editor, reference_keys, evidence_choices):\\n    controller = install_inline(editor)\\n    previous = controller.loading\\n    controller.loading = True\\n    try:\\n        for field in editor.spec.fields:\\n            kind = field.kind\\n            widget = editor.widgets[field.name]\\n            if kind == \\"evidence_multi\\":\\n                widget.set_options(evidence_choices(editor.app.source_directory))\\n            elif kind in DROPDOWN_KINDS:\\n                if kind == \\"bool\\":\\n                    choices = (\\"true\\", \\"false\\")\\n                elif kind == \\"choice\\":\\n                    choices = field.choices\\n                elif kind == \\"collection_type_ref\\":\\n                    collection_kind = controller.changes.get(\\"collection_kind\\")\\n                    if collection_kind is None:\\n                        kinds = {controller.original[int(item)].get(\\"collection_kind\\", \\"\\") for item in controller.selection}\\n                        collection_kind = next(iter(kinds)) if len(kinds) == 1 else None\\n                    choices = reference_keys(editor.app.source_directory, field, collection_kind)\\n                else:\\n                    choices = reference_keys(editor.app.source_directory, field)\\n                widget.configure(values=tuple(dict.fromkeys((\\"\\",) + tuple(choices))))\\n    finally:\\n        controller.loading = previous\\n\\n\\ndef apply_inline(editor, validate, decimal_check):\\n    controller = install_inline(editor)\\n    if not controller.active:\\n        editor._set_status(\\"Batch Apply blocked: reselect the rows before editing.\\")\\n        return False\\n    changes = dict(controller.changes)\\n    try:\\n        applied = apply_to_draft(\\n            editor, controller.selection, controller.original, changes, validate, decimal_check,\\n        )\\n    except (ValueError, OSError, UnicodeError, csv.Error) as error:\\n        message = str(error)\\n        log = getattr(editor.app, \\"log\\", None)\\n        if callable(log):\\n            log(f\\"[{editor.spec.table}] Batch Apply blocked; draft retained: {message}\\")\\n        editor._set_status(\\"Batch Apply blocked: \\" + message.splitlines()[0] + \\" See Activity Log.\\")\\n        return False\\n    if not applied:\\n        editor._set_status(\\"No deliberately edited fields. Draft unchanged.\\")\\n        return False\\n    selection = controller.selection\\n    for selected in selection:\\n        index = int(selected)\\n        editor.tree.item(selected, values=[\\n            editor.rows[index].get(field.name, \\"\\") for field in editor.spec.fields if not field.multiline\\n        ])\\n    controller.begin(selection, force=True)\\n    editor._ref_choices()\\n    editor._set_status(\\n        f\\"Updated {len(selection)} draft rows; {len(changes)} field(s). UNSAVED CHANGES.\\"\\n    )\\n    return True\\n", "tests/test_inline_bulk_edit.py": "import ast\\nimport copy\\nimport inspect\\nimport unittest\\nfrom types import SimpleNamespace as NS\\nfrom unittest.mock import Mock\\n\\nimport doda_bulk_edit as bulk\\nimport doda_inline_bulk_edit as inline\\nimport doda_multiselect as multi\\n\\n\\nclass Variable:\\n    def __init__(self, value=\\"\\"):\\n        self.value = value\\n        self.callbacks = []\\n    def get(self):\\n        return self.value\\n    def set(self, value):\\n        self.value = value\\n        for callback in self.callbacks:\\n            callback()\\n    def trace_add(self, mode, callback):\\n        self.callbacks.append(callback)\\n        return str(len(self.callbacks))\\n\\n\\nclass Widget:\\n    def __init__(self, state=\\"normal\\", values=()):\\n        self.state = state\\n        self.values = values\\n        self.bindings = {}\\n        self.selection_range = Mock()\\n        self.icursor = Mock()\\n        self.set_options = Mock()\\n    def cget(self, name):\\n        return self.values if name == \\"values\\" else self.state\\n    def configure(self, **kwargs):\\n        self.state = kwargs.get(\\"state\\", self.state)\\n        self.values = kwargs.get(\\"values\\", self.values)\\n    def bind(self, event, callback, **kwargs):\\n        self.bindings[event] = callback\\n    def after_idle(self, callback):\\n        callback()\\n\\n\\ndef field(name, kind=\\"text\\", required=False, choices=()):\\n    return NS(name=name, label=name, kind=kind, required=required, choices=choices, multiline=False)\\n\\n\\nclass InlineBulkTests(unittest.TestCase):\\n    def setUp(self):\\n        fields = (\\n            field(\\"id\\", required=True), field(\\"count\\", \\"int\\"), field(\\"blank\\"),\\n            field(\\"active\\", \\"bool\\", choices=()), field(\\"evidence\\", \\"evidence_multi\\"),\\n        )\\n        self.editor = NS(\\n            spec=NS(table=\\"example\\", fields=fields, key_columns=(\\"id\\",)),\\n            rows=[dict(id=\\"A\\", count=\\"3\\", blank=\\"\\", active=\\"false\\", evidence=\\"\\"),\\n                  dict(id=\\"B\\", count=\\"7\\", blank=\\"\\", active=\\"false\\", evidence=\\"\\"),\\n                  dict(id=\\"C\\", count=\\"9\\", blank=\\"\\", active=\\"false\\", evidence=\\"\\")],\\n            vars={f.name: Variable() for f in fields},\\n            widgets={f.name: Widget(\\"readonly\\" if f.kind == \\"bool\\" else \\"normal\\", (\\"true\\", \\"false\\") if f.kind == \\"bool\\" else ()) for f in fields},\\n            tree=Mock(), app=NS(project_root=\\"root\\", source_directory=\\"source\\", log=Mock()),\\n            _set_status=Mock(), _ref_choices=Mock(), dirty=False,\\n        )\\n        self.editor.tree.selection.return_value = (\\"0\\", \\"1\\")\\n        self.controller = inline.install_inline(self.editor)\\n        self.controller.begin((\\"0\\", \\"1\\"))\\n\\n    def valid(self):\\n        return Mock(return_value=NS(valid=True, errors=[]))\\n\\n    def test_same_and_different_populated_fields_show_placeholder(self):\\n        self.assertEqual(self.editor.vars[\\"count\\"].get(), \\"Multiple values\\")\\n        self.assertEqual(self.editor.vars[\\"active\\"].get(), \\"Multiple values\\")\\n\\n    def test_all_blank_fields_stay_blank(self):\\n        self.assertEqual(self.editor.vars[\\"blank\\"].get(), \\"\\")\\n        self.assertEqual(self.editor.vars[\\"evidence\\"].get(), \\"\\")\\n\\n    def test_only_keys_are_disabled(self):\\n        self.assertEqual(self.editor.widgets[\\"id\\"].state, \\"disabled\\")\\n        self.assertEqual(self.editor.widgets[\\"count\\"].state, \\"normal\\")\\n        self.assertEqual(self.editor.widgets[\\"active\\"].state, \\"readonly\\")\\n\\n    def test_loading_selection_does_not_mark_edits(self):\\n        self.assertEqual(self.controller.changes, {})\\n        self.assertFalse(self.editor.dirty)\\n\\n    def test_focus_selects_placeholder_without_changing_data(self):\\n        self.controller.focus(\\"count\\")\\n        self.editor.widgets[\\"count\\"].selection_range.assert_called_once_with(0, \\"end\\")\\n        self.assertEqual(self.editor.vars[\\"count\\"].get(), \\"Multiple values\\")\\n        self.assertEqual(self.controller.changes, {})\\n\\n    def test_click_blank_field_does_not_mark_edits(self):\\n        self.controller.focus(\\"blank\\")\\n        self.editor.widgets[\\"blank\\"].selection_range.assert_not_called()\\n        self.assertEqual(self.controller.changes, {})\\n\\n    def test_input_tracks_only_edited_field(self):\\n        self.editor.vars[\\"count\\"].set(\\"4\\")\\n        self.assertEqual(self.controller.changes, {\\"count\\": \\"4\\"})\\n        self.assertFalse(self.editor.dirty)\\n\\n    def test_new_value_in_blank_field(self):\\n        self.editor.vars[\\"blank\\"].set(\\"new\\")\\n        self.assertEqual(self.controller.changes, {\\"blank\\": \\"new\\"})\\n\\n    def test_explicit_clear_is_tracked(self):\\n        self.editor.vars[\\"count\\"].set(\\"\\")\\n        self.assertEqual(self.controller.changes, {\\"count\\": \\"\\"})\\n        self.assertTrue(inline.apply_inline(self.editor, self.valid(), None))\\n        self.assertEqual([r[\\"count\\"] for r in self.editor.rows], [\\"\\", \\"\\", \\"9\\"])\\n\\n    def test_key_writes_cannot_enter_change_map(self):\\n        self.editor.vars[\\"id\\"].set(\\"NEW\\")\\n        self.assertEqual(self.controller.changes, {})\\n\\n    def test_untouched_apply_changes_nothing(self):\\n        before=copy.deepcopy(self.editor.rows)\\n        validate=self.valid()\\n        self.assertFalse(inline.apply_inline(self.editor, validate, None))\\n        self.assertEqual(self.editor.rows, before)\\n        self.assertFalse(self.editor.dirty)\\n        validate.assert_not_called()\\n\\n    def test_apply_changes_only_selected_field_and_rows(self):\\n        self.editor.vars[\\"blank\\"].set(\\"new\\")\\n        self.assertTrue(inline.apply_inline(self.editor, self.valid(), None))\\n        self.assertEqual([r[\\"count\\"] for r in self.editor.rows], [\\"3\\", \\"7\\", \\"9\\"])\\n        self.assertEqual([r[\\"blank\\"] for r in self.editor.rows], [\\"new\\", \\"new\\", \\"\\"])\\n        self.assertTrue(self.editor.dirty)\\n        self.assertEqual(self.controller.changes, {})\\n        self.assertEqual(self.editor.vars[\\"blank\\"].get(), \\"Multiple values\\")\\n\\n    def test_invalid_integer_retains_all_rows_and_edit(self):\\n        before=copy.deepcopy(self.editor.rows)\\n        self.editor.vars[\\"count\\"].set(\\"bad\\")\\n        self.assertFalse(inline.apply_inline(self.editor, self.valid(), None))\\n        self.assertEqual(self.editor.rows, before)\\n        self.assertEqual(self.editor.vars[\\"count\\"].get(), \\"bad\\")\\n        self.assertFalse(self.editor.dirty)\\n\\n    def test_placeholder_cannot_be_applied(self):\\n        self.editor.vars[\\"blank\\"].set(\\"Multiple values\\")\\n        self.assertFalse(inline.apply_inline(self.editor, self.valid(), None))\\n        self.assertFalse(self.editor.dirty)\\n        self.assertEqual(self.editor.rows[0][\\"blank\\"], \\"\\")\\n\\n    def test_full_validation_failure_is_atomic(self):\\n        before=copy.deepcopy(self.editor.rows)\\n        self.editor.vars[\\"count\\"].set(\\"4\\")\\n        validate=Mock(return_value=NS(valid=False, errors=[\\"row two invalid\\"]))\\n        self.assertFalse(inline.apply_inline(self.editor, validate, None))\\n        self.assertEqual(self.editor.rows, before)\\n        self.assertEqual(self.controller.changes, {\\"count\\": \\"4\\"})\\n        self.editor.app.log.assert_called_once()\\n\\n    def test_validation_exception_preserves_previous_dirty_draft(self):\\n        self.editor.dirty=True\\n        before=copy.deepcopy(self.editor.rows)\\n        self.editor.vars[\\"count\\"].set(\\"4\\")\\n        self.assertFalse(inline.apply_inline(self.editor, Mock(side_effect=OSError(\\"read failed\\")), None))\\n        self.assertEqual(self.editor.rows, before)\\n        self.assertTrue(self.editor.dirty)\\n\\n    def test_same_selection_event_preserves_pending_edits(self):\\n        self.editor.vars[\\"count\\"].set(\\"4\\")\\n        self.controller.begin((\\"0\\", \\"1\\"))\\n        self.assertEqual(self.controller.changes, {\\"count\\": \\"4\\"})\\n        self.assertEqual(self.editor.vars[\\"count\\"].get(), \\"4\\")\\n\\n    def test_different_selection_resets_unapplied_fields(self):\\n        self.editor.vars[\\"count\\"].set(\\"4\\")\\n        self.controller.begin((\\"1\\", \\"2\\"))\\n        self.assertEqual(self.controller.changes, {})\\n        self.assertEqual(self.editor.rows[0][\\"count\\"], \\"3\\")\\n\\n    def test_end_restores_dropdown_values_and_stops_tracking(self):\\n        self.editor.widgets[\\"active\\"].values=(\\"\\", \\"true\\", \\"false\\")\\n        self.controller.end()\\n        self.assertEqual(self.editor.widgets[\\"active\\"].values, (\\"true\\", \\"false\\"))\\n        self.assertFalse(self.editor.widgets[\\"evidence\\"]._bulk_mode)\\n        self.editor.vars[\\"count\\"].set(\\"8\\")\\n        self.assertEqual(self.controller.changes, {})\\n\\n    def test_stale_selection_rejected(self):\\n        before=copy.deepcopy(self.editor.rows)\\n        self.editor.vars[\\"count\\"].set(\\"4\\")\\n        self.editor.tree.selection.return_value=(\\"1\\", \\"2\\")\\n        self.assertFalse(inline.apply_inline(self.editor, self.valid(), None))\\n        self.assertEqual(self.editor.rows, before)\\n\\n    def test_refresh_adds_blank_without_marking_changes(self):\\n        inline.refresh_inline_choices(self.editor, Mock(), Mock(return_value=[]))\\n        self.assertEqual(self.editor.widgets[\\"active\\"].values, (\\"\\", \\"true\\", \\"false\\"))\\n        self.assertEqual(self.controller.changes, {})\\n\\n    def test_evidence_commit_does_not_preserve_placeholder(self):\\n        variable=Variable(\\"Multiple values\\")\\n        obj=NS(variable=variable, options=[(\\"EVIDENCE_A\\", \\"A\\")],\\n               flags={\\"EVIDENCE_A\\":NS(get=lambda:True)}, _bulk_mode=True)\\n        multi.MultiSelectDropdown._commit(obj)\\n        self.assertEqual(variable.get(), \\"EVIDENCE_A\\")\\n\\n    def test_evidence_blank_summary_is_blank_in_bulk_mode(self):\\n        obj=NS(variable=Variable(\\"\\"), summary=Variable(), options=[], flags={}, _bulk_mode=True)\\n        multi.MultiSelectDropdown._sync(obj)\\n        self.assertEqual(obj.summary.get(), \\"\\")\\n\\n    def test_evidence_single_mode_keeps_original_prompt(self):\\n        obj=NS(variable=Variable(\\"\\"), summary=Variable(), options=[], flags={})\\n        multi.MultiSelectDropdown._sync(obj)\\n        self.assertEqual(obj.summary.get(), \\"Select evidence types...\\")\\n\\n    def test_no_bulk_window_code_remains(self):\\n        for module in (inline, bulk):\\n            tree=ast.parse(inspect.getsource(module))\\n            self.assertFalse(any(isinstance(n,ast.Attribute) and n.attr==\\"Toplevel\\" for n in ast.walk(tree)))\\n        self.assertFalse(hasattr(bulk, \\"open_bulk_editor\\"))\\n"}, "baseline_minimum": 731, "added_tests": 28}')
root = Path(sys.argv[1]).resolve()
module = root / "tools" / "doda_content_workbench"
source = root / "data_authoring" / "source"
if not module.is_dir() or not source.is_dir():
    raise SystemExit("Project directories missing; nothing installed.")

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None

def guard():
    failures=[]
    for name, expected in payload["guards"].items():
        actual=sha(module / name)
        if actual != expected:
            failures.append(f"{name}: expected {expected}, actual {actual}")
    for name in payload["new_files"]:
        if (module / name).exists():
            failures.append(name + ": target already exists")
    if failures:
        raise RuntimeError("GUARD FAILED. Inspect current local files; do not bypass.\n" + "\n".join(failures))

try:
    guard()
except Exception as error:
    print(error)
    raise SystemExit(1)
source_bytes={p.relative_to(source).as_posix():p.read_bytes() for p in source.rglob("*.csv")}
if not source_bytes:
    raise SystemExit("No source CSVs found; nothing installed.")

def source_unchanged():
    current={p.relative_to(source).as_posix():p.read_bytes() for p in source.rglob("*.csv")}
    if current != source_bytes:
        changed=sorted(k for k in set(current) | set(source_bytes) if current.get(k) != source_bytes.get(k))
        raise RuntimeError("Source CSVs changed during the operation: " + ", ".join(changed))

stamp=datetime.now().strftime("%Y%m%d_%H%M%S") + "_" + uuid4().hex[:8]
backup=module / "backups" / ("v123_inline_bulk_" + stamp)
backup.mkdir(parents=True)
modified_names=sorted(set(p[0] for p in payload["replacements"]) | set(payload["replacements_full"]))
originals={name:(module / name).read_bytes() for name in modified_names}
for name,data in originals.items():
    dest=backup / "modified_files" / name
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_bytes(data)
for name,data in source_bytes.items():
    dest=backup / "source_csv_snapshot" / name
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_bytes(data)
(backup / "source_manifest.json").write_text(json.dumps({name:hashlib.sha256(data).hexdigest() for name,data in source_bytes.items()},indent=2),encoding="utf-8")
print("Backup and logs:",backup,flush=True)

def run_suite(label,minimum):
    env=dict(os.environ)
    env["PYTHONPATH"]=str(module) + os.pathsep + env.get("PYTHONPATH","")
    env["PYTHONDONTWRITEBYTECODE"]="1"
    done=subprocess.run(
        [sys.executable,"-m","unittest","discover","-s",str(module / "tests"),"-p","test_*.py"],
        cwd=root,env=env,text=True,encoding="utf-8",errors="replace",
        stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=900,
    )
    (backup / (label + ".log")).write_text(done.stdout,encoding="utf-8")
    print(done.stdout,flush=True)
    counts=re.findall(r"Ran (\d+) tests? in",done.stdout)
    count=int(counts[-1]) if counts else 0
    if done.returncode != 0 or count < minimum:
        raise RuntimeError(f"{label} failed: exit {done.returncode}, tests {count}, required >= {minimum}.")
    source_unchanged()
    return count

def get_function(data,name,class_name=None):
    tree=ast.parse(data.decode("utf-8-sig"))
    nodes=tree.body
    if class_name:
        nodes=next(n for n in nodes if isinstance(n,ast.ClassDef) and n.name==class_name).body
    return ast.dump(next(n for n in nodes if isinstance(n,ast.FunctionDef) and n.name==name),include_attributes=False)

written={}
try:
    baseline=run_suite("baseline",payload["baseline_minimum"])
    guard()
    candidates={}
    for name,data in originals.items():
        text=data.decode("utf-8-sig").replace("\r\n","\n")
        if name in payload["replacements_full"]:
            text=payload["replacements_full"][name]
        else:
            for target,old,new in payload["replacements"]:
                if target != name:
                    continue
                if text.count(old) != 1:
                    raise RuntimeError("Content guard failed: " + name + ". Inspect the current file.")
                text=text.replace(old,new)
        ast.parse(text)
        newline="\r\n" if b"\r\n" in data else "\n"
        encoded=text.replace("\n",newline).encode("utf-8")
        if data.startswith(b"\xef\xbb\xbf"):
            encoded=b"\xef\xbb\xbf" + encoded
        candidates[name]=encoded
    for name,text in payload["new_files"].items():
        ast.parse(text)
        candidates[name]=text.encode("utf-8")
    for name in ("save",):
        if get_function(originals["doda_network_editor.py"],name,"NetworkTableEditor") != get_function(candidates["doda_network_editor.py"],name,"NetworkTableEditor"):
            raise RuntimeError("Save safeguard preservation check failed.")
    for name in ("_sha","write_rows","validate_candidate"):
        if get_function(originals["doda_network_editor.py"],name) != get_function(candidates["doda_network_editor.py"],name):
            raise RuntimeError("Source safeguard preservation check failed: " + name)
    if get_function(originals["doda_bulk_edit.py"],"build_candidate") != get_function(candidates["doda_bulk_edit.py"],"build_candidate"):
        raise RuntimeError("Atomic batch validation preservation check failed.")
    guard()
    source_unchanged()
    for name,data in candidates.items():
        path=module / name
        temporary=path.with_name("." + path.name + "." + uuid4().hex + ".tmp")
        try:
            temporary.write_bytes(data)
            if name in originals and path.read_bytes() != originals[name]:
                raise RuntimeError("File changed before write: " + name)
            if name not in originals and path.exists():
                raise RuntimeError("New file appeared before write: " + name)
            os.replace(temporary,path)
            written[name]=data
        finally:
            temporary.unlink(missing_ok=True)
    after=run_suite("post_install",baseline + payload["added_tests"])
    source_unchanged()
    for name,data in written.items():
        if (module / name).read_bytes() != data:
            raise RuntimeError("Installed code changed during tests: " + name)
    for name,expected in payload["guards"].items():
        if name not in written and sha(module / name) != expected:
            raise RuntimeError("Unmodified guarded file changed during tests: " + name)
    hashes={name:sha(module / name) for name in written}
    (backup / "installed_hashes.json").write_text(json.dumps(hashes,indent=2),encoding="utf-8")
    print(f"V123 INSTALLED: baseline {baseline}, post-install {after}; {len(source_bytes)} source CSVs unchanged.")
    print("Shared Record-panel bulk editing enabled. Task Templates unchanged. Manual GUI check required.")
    print(json.dumps(hashes,indent=2))
except BaseException as error:
    failures=[]
    for name,data in reversed(list(written.items())):
        path=module / name
        try:
            if not path.is_file() or path.read_bytes() != data:
                raise RuntimeError("Current file differs from patch output; refusing to overwrite external edits.")
            if name in originals:
                temporary=path.with_name("." + path.name + ".rollback." + uuid4().hex)
                try:
                    temporary.write_bytes(originals[name])
                    os.replace(temporary,path)
                finally:
                    temporary.unlink(missing_ok=True)
                if path.read_bytes() != originals[name]:
                    raise RuntimeError("Rollback verification failed.")
            else:
                path.unlink()
        except Exception as rollback_error:
            failures.append(name + ": " + str(rollback_error))
    print("INSTALLATION STOPPED:",str(error))
    print("Patched files rolled back." if not failures else "ROLLBACK NEEDS INSPECTION:\n" + "\n".join(failures))
    try:
        source_unchanged()
        print("Source CSVs unchanged.")
    except Exception as source_error:
        print(source_error)
        print("Source snapshot retained in backup. No CSV is overwritten automatically; inspect before restoration.")
    print("Backup and logs:",backup)
    raise SystemExit(1)

'@
$temporary = Join-Path $env:TEMP ('doda_v123_' + [guid]::NewGuid().ToString('N') + '.py')
try {
    [IO.File]::WriteAllText($temporary, $code, (New-Object System.Text.UTF8Encoding($false)))
    & $python $temporary $Root
    if ($LASTEXITCODE -ne 0) { throw "v123 stopped with exit code $LASTEXITCODE. Inspect the reported log/backup before retrying." }
} finally {
    Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue
}
